import type { ProjectDefinition, QuestGuideFrame, QuestGuideScene, QuestLink, QuestStep } from "./types";

export const API_KEYS_QUEST_HREF = "?quest=api-keys";

export const setupQuestSlugs = ["install-codex", "server-152fz", "api-keys"] as const;
export type SetupQuestSlug = (typeof setupQuestSlugs)[number];

type SetupStepInput = {
  id: number;
  title: string;
  eyebrow: string;
  why: string;
  action: string;
  expected: [string, string, string];
  app: string;
  scene?: QuestGuideScene;
  target: string;
  help: string;
  prompt?: string;
  links?: QuestLink[];
};

const external = (label: string, href: string, note: string): QuestLink => ({ label, href, note, external: true });
const apiLessonLink: QuestLink = {
  label: "Сначала пройти квест «Добавляем API-ключи»",
  href: API_KEYS_QUEST_HREF,
  note: "Там показано, где получить ключ и как передать его проекту, не публикуя секрет.",
};

function searchableText(step: QuestStep): string {
  return [step.title, step.why, step.action, step.prompt, ...step.expected].filter(Boolean).join(" ");
}

export function needsApiKeysQuestLink(step: QuestStep): boolean {
  return /(?:API|апи)[-‑ ]?(?:ключ|key)/i.test(searchableText(step));
}

export function attachApiKeysQuestLinks(steps: QuestStep[], projectSlug: string): QuestStep[] {
  if (projectSlug === "api-keys") return steps;
  return steps.map((step) => {
    if (!needsApiKeysQuestLink(step)) return step;
    const links = step.links ?? [];
    if (links.some((link) => link.href === API_KEYS_QUEST_HREF)) return step;
    return { ...step, links: [apiLessonLink, ...links] };
  });
}

function guide(project: ProjectDefinition, input: SetupStepInput): QuestGuideFrame[] {
  const base = `/guides/${project.slug}/step-${String(input.id).padStart(2, "0")}`;
  return [
    {
      id: 1,
      title: `Откройте ${input.app}`,
      app: input.app,
      action: `Откройте ${input.app}. Сверьте название страницы или окна со скриншотом. Не нажимайте дальше, пока не убедитесь, что открыто именно то место, о котором говорит уровень.`,
      after: `На экране видно нужное окно для уровня «${input.title}».`,
      doneWhen: `Название окна и основная кнопка совпадают со скриншотом уровня ${input.id}.`,
      fallback: `Если экран другой, вернитесь в Академию, ещё раз нажмите официальную ссылку этого уровня и не используйте рекламные ссылки из поиска.`,
      screenshot: `${base}-frame-01.png`,
      scene: input.scene ?? "academy",
      target: input.target,
    },
    {
      id: 2,
      title: input.title,
      app: input.app,
      action: input.action,
      exactText: input.prompt,
      after: input.expected[0],
      doneWhen: input.expected[1],
      fallback: input.help,
      screenshot: `${base}-frame-02.png`,
      scene: input.scene ?? "academy",
      target: input.target,
    },
    {
      id: 3,
      title: "Остановитесь и сверьте результат",
      app: input.app,
      action: `Ничего больше не меняйте. По очереди найдите на своём экране три признака: «${input.expected.join("», «")}». Только после этого отмечайте уровень выполненным.`,
      after: input.expected.join(" · "),
      doneWhen: input.expected.join("; "),
      fallback: `Если не совпадает хотя бы один пункт, откройте «Нужна помощь» и отправьте куратору или ChatGPT готовый текст. Не создавайте второй аккаунт, второй сервер или новый ключ наугад.`,
      screenshot: `${base}-frame-03.png`,
      scene: input.scene ?? "preview",
      target: "Три признака готовности",
    },
  ];
}

function makeStep(project: ProjectDefinition, input: SetupStepInput): QuestStep {
  return {
    id: input.id,
    title: input.title,
    eyebrow: input.eyebrow,
    why: input.why,
    action: input.action,
    kind: input.prompt ? "prompt" : "action",
    prompt: input.prompt,
    expected: input.expected,
    screenshot: `/screens/${project.slug}/step-${String(input.id).padStart(2, "0")}.png`,
    reward: input.id === 8 ? "Фея безопасной настройки" : input.id === 17 ? "Хранительница рабочего места" : undefined,
    help: {
      title: `Помощь: ${input.title}`,
      body: input.help,
      prompt: `Я новичок и прохожу квест «${project.title}», уровень ${input.id} «${input.title}». Мой экран не совпал с ожидаемым результатом. Не проси меня писать код и не проси присылать пароль, платёжные данные, API-ключ или секрет. Задай один короткий вопрос о том, что я вижу на экране, затем объясни одно безопасное действие обычными словами.`,
    },
    links: input.links,
    guide: guide(project, input),
  };
}

